	@Test
	void closeWaitsForInFlightApplyBeforeRetiringPublishedBase() throws Exception {
		commitQuads(new long[][] { add(S1, P1, O1, 0, true) });
		recreateStore(Map.of(LmdbDirectAdjacencyOptions.SYNCHRONOUS_MAINTENANCE_PROPERTY, "false"));
		assertThat(store.buildNowForTest()).isTrue();

		long[][] additions = new long[65_536][];
		for (int i = 0; i < additions.length; i++) {
			additions[i] = add(uri(10_000L + i), P1, uri(1_000_000L + i), 0, true);
		}
		commitQuads(additions);
		long committedRevision = tripleStore.getDataRevision();
		LmdbAdjacencyMemoryAccount account = store.memoryAccount();
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(30);
		boolean observedInFlight = false;
		while (System.nanoTime() < deadline) {
			LmdbAdjacencyPublishedState state = store.publishedStateForTest();
			if (account.chargedBytes(MemoryKind.DELTA) > 0
					&& state.appliedRevision() < committedRevision) {
				observedInFlight = true;
				break;
			}
			Thread.onSpinWait();
		}
		assertThat(observedInFlight).as("delta apply must reach its reserved-but-unpublished phase").isTrue();

		LmdbDirectAdjacencyStore closingStore = store;
		closingStore.close();
		store = null;

		assertThat(closingStore.maintenanceState()).isEqualTo(LmdbDirectAdjacencyStore.MaintenanceState.CLOSED);
		assertThat(account.totalChargedBytes()).isZero();
	}

	@Test
	void closeWithAHeldBuildCandidateAndAnUnappliedCommitIsPrompt() throws Exception {
		commitQuads(new long[][] { add(S1, P1, O1, 0, true) });
		recreateStore(Map.of(LmdbDirectAdjacencyOptions.SYNCHRONOUS_MAINTENANCE_PROPERTY, "false"));
		ApplierStepping.holdBuildAfterScan(store);
		// a commit beside the held candidate lands in the log; close must not wait for either to be applied
		tripleStore.startTransaction();
		tripleStore.storeTriple(S3, P1, O2, 0, true);
		tripleStore.commit();
		store.applyCommitted(tripleStore.drainDirectAdjacencyCommitDelta(), false);

		LmdbDirectAdjacencyStore closingStore = store;
		long started = System.nanoTime();
		closingStore.close();
		long elapsed = System.nanoTime() - started;
		store = null;

		assertThat(elapsed).isLessThan(TimeUnit.SECONDS.toNanos(5));
		assertThat(closingStore.maintenanceState()).isEqualTo(LmdbDirectAdjacencyStore.MaintenanceState.CLOSED);
		assertThat(closingStore.memoryAccount().totalChargedBytes()).isZero();
	}
